Subroutine Suspendable Contar(nombre As String, canal As Channel<Integer>)
  For i <- 1 To 2 Do
    Write nombre, " ", i;
    If Not Await canal.send(i) Then
      Return;
    EndIf
  EndFor
EndSubroutine

Algorithm Turnos
  Define canal As Channel<Integer> <- channel(4);
  Tasks
    Spawn Contar("A", canal);
    Spawn Contar("B", canal);
    Write "padre";
  EndTasks
EndAlgorithm

Subroutine Suspendable Esperar(canal As Channel<Integer>)
  Switch Await canal.receive() Do
    Some(valor): Write valor;
    None: Write "cerrado";
  EndSwitch
EndSubroutine

Algorithm Bloqueo
  Define canal As Channel<Integer> <- channel(1);
  Tasks
    Spawn Esperar(canal);
  EndTasks
EndAlgorithm
